using System.Text.Json;
using KalTerm.Core.Money;
using KalTerm.Kalshi.Books;
using KalTerm.Kalshi.Models;
using KalTerm.Kalshi.Models.Json;

namespace KalTerm.Kalshi.Tests.Books;

/// <summary>
/// The book builder against the reference's own: every scenario in the golden vectors (generated by replaying scripted message streams through the Python
/// <c>BookTracker</c>) is replayed here, and after every step the events, every book and the stale set must be what the reference said.
/// </summary>
public class BookTrackerVectorTests
{
    private static readonly JsonElement Vectors = VectorFile.Load("orderbook.json");

    public static TheoryData<string> ScenarioNames()
    {
        var names = new TheoryData<string>();
        foreach (var scenario in Vectors.GetProperty("scenarios").EnumerateArray())
        {
            names.Add(scenario.GetProperty("name").GetString()!);
        }

        return names;
    }

    [Fact]
    public void TheVectorsHoldTheScenariosTheyShould()
    {
        Assert.True(Vectors.GetProperty("scenarios").GetArrayLength() >= 25);
    }

    [Theory]
    [MemberData(nameof(ScenarioNames))]
    public void ReplayingAScenarioGivesWhatTheReferenceGave(string name)
    {
        var scenario = Vectors.GetProperty("scenarios").EnumerateArray().Single(s => s.GetProperty("name").GetString() == name);
        var steps = scenario.GetProperty("steps").EnumerateArray().ToList();
        var expected = scenario.GetProperty("expect").EnumerateArray().ToList();
        var tracker = new BookTracker();

        for (var i = 0; i < steps.Count; i++)
        {
            var events = Apply(tracker, steps[i]);
            var where = $"step {i + 1} of '{name}'";

            Assert.True(events.Count == expected[i].GetProperty("events").GetArrayLength(), $"{where}: {events.Count} event(s)");
            var wanted = expected[i].GetProperty("events").EnumerateArray().ToList();
            for (var e = 0; e < events.Count; e++)
            {
                AssertEvent(wanted[e], events[e], $"{where}, event {e + 1}");
            }

            var books = expected[i].GetProperty("books").EnumerateObject().ToList();
            Assert.Equal(books.Select(b => b.Name), tracker.Books.Keys.Order(StringComparer.Ordinal));
            foreach (var book in books)
            {
                AssertBook(book.Value, tracker.Books[book.Name], $"{where}, book {book.Name}");
            }

            Assert.Equal(expected[i].GetProperty("stale").EnumerateArray().Select(s => s.GetString()), tracker.Stale.Order(StringComparer.Ordinal));
        }
    }

    private static IReadOnlyList<BookEvent> Apply(BookTracker tracker, JsonElement step)
    {
        switch (step.GetProperty("op").GetString())
        {
            case "message":
                return tracker.Process(KalshiJson.Parse(step.GetProperty("message").GetRawText(), KalshiJsonContext.Default.WsMessage, "scenario message"));
            case "begin_subscription":
                tracker.BeginSubscription(step.GetProperty("sid").GetInt32(), Tickers(step));
                return [];
            case "end_subscription":
                tracker.EndSubscription(step.GetProperty("sid").GetInt32());
                return [];
            case "begin_markets":
                tracker.BeginMarkets(step.GetProperty("sid").GetInt32(), Tickers(step));
                return [];
            case "forget_markets":
                tracker.ForgetMarkets(step.GetProperty("sid").GetInt32(), Tickers(step));
                return [];
            case "rest_snapshot":
                return [tracker.ApplyRestSnapshot(step.GetProperty("ticker").GetString()!, new OrderBook(Levels(step.GetProperty("yes")), Levels(step.GetProperty("no"))))];
            default:
                throw new InvalidOperationException("unknown step " + step);
        }
    }

    private static List<string> Tickers(JsonElement step) => [.. step.GetProperty("tickers").EnumerateArray().Select(t => t.GetString()!)];

    private static List<PriceLevel> Levels(JsonElement levels) =>
        [.. levels.EnumerateArray().Select(l => new PriceLevel(Dollars.Parse(l[0].GetString()), Contracts.Parse(l[1].GetString())))];

    private static void AssertEvent(JsonElement expected, BookEvent actual, string where)
    {
        Assert.True(expected.GetProperty("kind").GetString() == actual.Kind, $"{where}: kind {actual.Kind}");
        Assert.True(Nullable(expected.GetProperty("ticker")) == actual.Ticker, $"{where}: ticker {actual.Ticker}");
        Assert.Equal(expected.GetProperty("tickers").EnumerateArray().Select(t => t.GetString()), actual.AffectedTickers);
        Assert.True(expected.GetProperty("detail").GetString() == actual.Detail, $"{where}: detail '{actual.Detail}'");
        Assert.True(Nullable(expected.GetProperty("messageType")) == actual.Message?.Type, $"{where}: message type {actual.Message?.Type}");
        if (expected.GetProperty("book").ValueKind == JsonValueKind.Null)
        {
            Assert.Null(actual.Book);
        }
        else
        {
            Assert.NotNull(actual.Book);
            AssertBook(expected.GetProperty("book"), actual.Book, where);
        }
    }

    private static void AssertBook(JsonElement expected, LocalOrderBook actual, string where)
    {
        Assert.True(expected.GetProperty("approximate").GetBoolean() == actual.Approximate, $"{where}: approximate");
        foreach (var side in new[] { "yes", "no" })
        {
            var wanted = expected.GetProperty(side).EnumerateArray().Select(l => $"{l[0].GetString()} x {l[1].GetString()}").ToList();
            var got = actual.Bids(side).Select(l => $"{l.Price} x {l.Quantity}").ToList();
            Assert.True(wanted.SequenceEqual(got), $"{where}: {side} levels were [{string.Join(", ", got)}], expected [{string.Join(", ", wanted)}]");
        }
    }

    private static string? Nullable(JsonElement value) => value.ValueKind == JsonValueKind.Null ? null : value.GetString();
}
